TEMAS_DB10 = [CV]

DEBATES10 = [
dict(s='tirar-a-vida', n='Tirar a vida de um ser senciente: qual é o dano da morte?', t=VM, r='Se a morte é indolor, o que ela tira de quem morre? A resposta decide o que pensar de eutanásia, aborto, abate e guerra.',
 v='Quase todo mundo acha que matar é grave. Mas é difícil dizer por quê, se a morte em si não é sentida: quem morre não sofre a própria ausência. Epicuro concluiu que a morte não é um mal para quem morre. A maioria dos filósofos atuais discorda, e a explicação que dão, o que a morte priva, tem consequências para humanos e para os outros animais.',
 lados=[('A morte é um dano para quem morre', ['Privação (Nagel, Feldman, Bradley): a morte é má porque tira o bem que a vida ainda teria, como um sono do qual não se acorda tira os dias seguintes. Não precisa ser sentida para ser uma perda, assim como uma traição nunca descoberta ainda é uma traição.', 'Interesses e desejos: um ser com planos, vínculos e desejos sobre o futuro tem esses desejos frustrados pela morte, mesmo que não saiba (Singer, para seres autoconscientes).', 'Graus (McMahan): o dano da morte depende de quanto futuro bom se perde e de quão ligado o ser está a esse futuro por memória, intenção e desejo; por isso a morte de um adulto jovem costuma ser pior do que a de alguém no fim da vida ou de um ser sem senso de futuro, sem deixar de ser um dano.', 'Para os animais: um animal que teria uma vida boa perde essa vida quando é morto, por mais indolor que seja o abate. “Vida feliz e morte sem dor” ainda é uma vida interrompida.']),
        ('A morte não é um dano, ou é um dano menor do que parece', ['Epicuro e Lucrécio: onde a morte está, eu não estou; não há sujeito para ser prejudicado, e não temíamos o tempo anterior ao nascimento, que é simétrico.', 'Resposta à privação: comparar “a vida que teria” exige um sujeito que a perde; depois da morte, não há ninguém em pior situação.', 'Substituibilidade: se o que importa é a quantidade de bem no mundo, um ser morto e substituído por outro igualmente feliz não reduz o total. O próprio Singer defendeu isso para seres sem autoconsciência, e depois passou a duvidar.', 'Morte boa: quando a vida que resta é só sofrimento, a morte deixa de ser privação e passa a ser alívio; a eutanásia voluntária parte daí.'])],
 c=['A simetria de Lucrécio tem resposta: antes de nascer não havia ninguém com um futuro a perder; na morte, há alguém que perde o futuro. A assimetria entre passado e futuro é um fato sobre nós, não um erro.', 'A substituibilidade só funciona para quem vê os indivíduos como recipientes de bem. Para quem acha que o ser que existe conta por si, substituir não compensa: o frango morto não é poupado pelo frango que nasce.', 'A conta de privação não implica que toda morte seja igualmente má, nem que seja sempre má: ela diz que matar um ser com futuro bom tira algo dele, e isso é o que a maioria das teorias chama de dano.'],
 p=('parcial', 'O peso está com a conta da privação: a morte prejudica quem morre porque tira o bem que a vida ainda teria, mesmo sem ser sentida, e isso vale em graus para todo ser senciente com um futuro bom, humano ou não. A posição epicurista aponta um problema real (quem é o sujeito do dano?) mas leva a conclusões que quase ninguém aceita, como a de que matar sem dor não lesa ninguém. O que fica em aberto é o peso: quanto o dano cresce com os planos, os vínculos e a duração do futuro perdido, e se a substituição alguma vez compensa.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'A morte é má pelo bem que deixa de existir; a substituibilidade é a consequência incômoda.'), ('utilitarismo-de-preferencias', 'Preferências', 'Matar frustra o desejo de continuar vivendo; o dano cresce com os planos do ser.'), ('deontologia-de-direitos', 'Direitos', 'Todo sujeito de uma vida tem direito a ela; matar sem dor continua violando-o (Regan).'), ('sencientismo', 'Sencientismo', 'A perda do futuro conta para qualquer ser que o teria vivido com bem-estar, sem distinção de espécie.'), ('gradualismo', 'Gradualismo', 'O dano da morte varia com a ligação do ser ao próprio futuro (McMahan).'), ('etica-focada-no-sofrimento', 'Foco no sofrimento', 'A morte sem dor não acrescenta sofrimento; o problema moral está na vida ruim antes dela, e na dor da morte violenta.')],
 licoes=['senciencia', 'especismo', 'teorias-do-bem-estar', 'etica-populacional', 'o-peso-do-sofrimento'],
 fx=[('Death (Stanford Encyclopedia)', SEP + 'death/'), ('Death', 'https://www.jstor.org/stable/4544815'), ('The Ethics of Killing', 'https://www.google.com/search?tbm=bks&q=McMahan+The+Ethics+of+Killing'), ('Well-Being and Death', 'https://www.google.com/search?tbm=bks&q=Ben+Bradley+Well-Being+and+Death'), ('Killing Happy Animals', 'https://www.google.com/search?tbm=bks&q=Tatjana+Visak+Killing+Happy+Animals')]),

dict(s='consequencias-regras-ou-carater', n='Em que focar: consequências, regras ou caráter?', t=FU, r='As três grandes famílias respondem a perguntas diferentes: o que produzir, o que fazer e quem ser. A disputa é sobre qual vem primeiro.',
 v='Diante de uma decisão, pode-se perguntar “o que vai acontecer?”, “o que devo fazer?” ou “o que uma pessoa boa faria?”. Consequencialismo, deontologia e ética das virtudes partem de uma dessas perguntas e tentam derivar as outras. Este debate é sobre o ponto focal: o que mais deve pesar quando as três respostas divergem. Nenhuma das três diz que o resto não importa.',
 lados=[('Consequências primeiro', ['Regras e virtudes valem pelo que produzem: uma regra que gerasse só desgraça não seria uma boa regra, e uma “virtude” que só fizesse mal não seria virtude. O resultado é o que dá sentido ao resto.', 'Só o foco no resultado tem resposta clara para conflitos entre regras e para casos novos, que as regras não previram.', 'Respeita o que acontece com quem recebe o ato: a vítima não se consola porque a regra foi seguida ou porque o agente tinha bom caráter.']),
        ('Regras e deveres primeiro', ['Há coisas que não se fazem a uma pessoa por nenhum resultado: usá-la como meio, mentir-lhe, tomar-lhe o que é seu. Esses limites são o que protege cada um da conta dos outros.', 'Regras dão previsibilidade e confiança; uma sociedade onde cada um calcula caso a caso é pior do que uma onde se pode contar com promessas e direitos. Até o consequencialista admite isso, e vira consequencialista de regras.', 'O cálculo de consequências é frágil: enviesado, incerto, fácil de torcer para justificar o que já se queria.']),
        ('Caráter primeiro', ['Ações saem de pessoas. Quem cultiva honestidade, coragem, compaixão e sabedoria prática decide bem sem precisar de uma fórmula; quem não as tem, nenhuma fórmula salva.', 'As regras precisam de juízo para serem aplicadas (que regra, quando, com que exceção), e esse juízo é a virtude da sabedoria prática. As regras não se aplicam sozinhas.', 'A ética não é só sobre decisões difíceis: é sobre como viver. A pergunta “que tipo de pessoa quero ser?” é anterior a “o que faço agora?”.'])],
 c=['As versões maduras de cada família incorporam as outras: o consequencialismo de regras valoriza normas; a deontologia de limiar cede ao resultado quando a catástrofe é grande; a ética das virtudes diz que o virtuoso se importa com as consequências e respeita regras. Parfit sugeriu que as três sobem o mesmo monte por lados diferentes.', 'A objeção às virtudes (“o que o virtuoso faria?” não guia quem ainda não é virtuoso) e a objeção às consequências (“o cálculo é frágil”) têm a mesma estrutura: cada abordagem precisa das outras para ser aplicável.', 'A pergunta prática raramente é “qual família é verdadeira?”, e sim “em que casos cada ponto focal erra?”: o consequencialista puro erra quando sacrifica um por muitos; o deontologista puro, quando segue a regra até a catástrofe; o virtuoso, quando confia no caráter onde faltam dados.'],
 p=('aberto', 'Não há consenso sobre qual ponto focal vem primeiro, e a tendência das últimas décadas é de convergência, não de vitória: as melhores versões de cada família já incluem as outras como componentes. O que se defende com mais força é um critério misto: resultados contam, e muito; há limites que não se cruzam por resultados comuns; e aplicar isso bem exige caráter. Onde o debate continua vivo é na ordem de justificação, no que explica o quê, e isso tem pouca consequência prática e muita consequência teórica.'),
 teorias=[('consequencialismo-de-ato', 'Consequencialismo de ato', 'Ponto focal: o resultado de cada ato; regras e virtudes são instrumentos.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Ponto focal: o resultado das regras aceitas por todos.'), ('deontologia-kantiana', 'Kant', 'Ponto focal: a máxima do ato e o respeito à pessoa; o resultado não redime o meio.'), ('deontologia-de-limiar', 'Deontologia de limiar', 'Regras pesam mais, até que o custo de segui-las fique catastrófico.'), ('etica-das-virtudes', 'Virtudes', 'Ponto focal: o caráter e a sabedoria prática de quem age.'), ('particularismo', 'Particularismo', 'Nenhum princípio geral decide; cada caso tem seu peso.')],
 licoes=['mapa-das-teorias', 'consequencialismo', 'deontologia', 'etica-do-carater', 'objecoes-ao-consequencialismo', 'pluralismo-de-valores'],
 fx=[('Consequentialism (Stanford Encyclopedia)', SEP + 'consequentialism/'), ('Deontological Ethics (Stanford Encyclopedia)', SEP + 'ethics-deontological/'), ('Virtue Ethics (Stanford Encyclopedia)', SEP + 'ethics-virtue/'), ('On What Matters', 'https://www.google.com/search?tbm=bks&q=Parfit+On+What+Matters')]),

dict(s='dano-sem-experiencia', n='Fazer mal a quem nunca vai saber: existe dano?', t=FU, r='Uma traição nunca descoberta, uma invasão de privacidade que a vítima jamais percebe. Se não há sofrimento, há dano? O debate sobre o requisito da experiência.',
 v='Imagine alguém que lê o diário de um amigo, espalha um segredo que nunca volta até a vítima, ou quebra uma promessa feita a quem já morreu. Ninguém sofre por isso; a vítima jamais saberá. Ainda assim quase todos julgam que algo errado aconteceu, e muitos dizem que a pessoa foi prejudicada. O que está em jogo é se o dano exige ser sentido (o chamado requisito da experiência) ou se um interesse pode ser lesado sem que o sujeito perceba. O tema tem nomes técnicos: experiencialismo contra teorias do desejo e da lista objetiva, no bem-estar; e dano sem vítima consciente, na filosofia do direito (Feinberg).',
 lados=[('Só o que é sentido conta (experiencialismo)', ['Hedonismo e teorias de estados mentais: bem-estar é feito de experiências; o que não entra na experiência de alguém não muda a vida dessa pessoa. A traição secreta não tornou a vida da vítima pior de dentro.', 'Vantagem: explica por que o sofrimento é o centro da moral e evita “danos” fantasmagóricos, como o dano a quem já morreu.', 'Como explica o erro: o ato é errado por outras razões, não por dano direto: pelo risco de ser descoberto, pelo que revela sobre o caráter de quem o faz, pela regra que seria ruim se todos seguissem.']),
        ('O dano não precisa ser sentido', ['Teorias do desejo: as pessoas querem coisas sobre o mundo, não só sobre as próprias sensações; querem que o amigo seja leal, não só sentir que ele é. Frustrar esse desejo lesa um interesse, com ou sem percepção (Nagel, Feinberg).', 'Lista objetiva: amizade genuína, respeito, privacidade e autonomia são bens em si; perdê-los é ser prejudicado, mesmo sem saber. A máquina de experiências de Nozick mostra que a maioria não troca a vida real por uma ilusão agradável.', 'Teste: se o experiencialismo estivesse certo, uma pessoa enganada a vida inteira por quem finge amá-la teria tido uma vida tão boa quanto a de quem foi de fato amada. Poucos aceitam isso.']),
        ('O erro independe do dano (deontologia)', ['O que torna o ato errado não é o resultado para a vítima, e sim o que se faz com ela: usar alguém sem consentimento, tratá-la como coisa, violar um limite que ela tinha direito de ver respeitado. Isso é errado antes de qualquer conta de dano.', 'Consentimento: tudo o que é feito a uma pessoa sem o seu acordo, e que ela teria direito de recusar, é uma violação, saiba ela ou não. É por isso que a lei pune a invasão de privacidade mesmo quando a vítima nunca descobre.', 'Caráter: quem age assim e se tranquiliza porque “ninguém vai saber” mostra que respeitava a pessoa só pelo medo de ser pego.'])],
 c=['O desacordo é sobre a explicação, não sobre o veredito: nenhuma das posições conclui que o ato é permitido. Até o experiencialista o condena, por razões indiretas.', 'O argumento da vida enganada é o mais forte contra o experiencialismo puro, e levou boa parte dos filósofos do bem-estar a adotar teorias do desejo ou da lista objetiva, ou a aceitar que o dano admite graus: ser enganado é pior se descoberto, mas já era mau antes.', 'A deontologia dá a resposta mais direta e a mais próxima da intuição comum: há coisas que não se fazem a uma pessoa, e “ela nunca vai saber” não é uma razão, é uma confissão.'],
 p=('forte', 'Há consenso sobre o veredito: fazer mal a alguém que nunca vai saber é errado, e nenhuma teoria séria diz o contrário. A disputa é sobre o porquê. A posição mais defendida combina duas respostas: a vítima é prejudicada, porque interesses em lealdade, privacidade e respeito podem ser lesados sem ser sentidos (o requisito da experiência é rejeitado pela maioria dos filósofos do bem-estar); e o ato violaria a pessoa mesmo que nenhum dano se provasse, por desrespeitar o consentimento que ela teria direito de dar ou negar.'),
 teorias=[('utilitarismo-classico', 'Hedonismo', 'Só experiências contam; o ato é errado pelo risco, pela regra e pelo caráter, não pelo dano direto.'), ('utilitarismo-de-preferencias', 'Preferências', 'Frustrar um desejo sobre o mundo é um dano, percebido ou não.'), ('deontologia-kantiana', 'Kant', 'Usar alguém sem seu consentimento é tratá-lo como meio; o segredo não muda isso.'), ('deontologia-de-direitos', 'Direitos', 'Privacidade e integridade são direitos; a violação não depende de ser descoberta.'), ('etica-das-virtudes', 'Virtudes', 'Quem só respeita quando observado não tem a virtude, tem o medo.'), ('contratualismo-escanloniano', 'Scanlon', 'Um princípio que permitisse violações secretas seria razoavelmente rejeitado por todos.')],
 licoes=['teorias-do-bem-estar', 'kant-e-o-imperativo-categorico', 'direitos-e-limiares', 'experimentos-mentais'],
 fx=[('Well-Being (Stanford Encyclopedia)', SEP + 'well-being/'), ('Death', 'https://www.jstor.org/stable/4544815'), ('Harm to Others', 'https://www.google.com/search?tbm=bks&q=Joel+Feinberg+Harm+to+Others'), ('Experience machine (Wikipédia)', WE + 'Experience_machine')]),

dict(s='pseudociencias', n='Pseudociências: acreditar é um problema moral?', t=CV, r='Astrologia, homeopatia, terapias sem evidência, negação de vacinas. Entre a liberdade de crer e o dano de agir, onde a ética entra.',
 v='Pseudociência é o que se apresenta com a autoridade da ciência sem seguir seus métodos: hipóteses que não se deixam testar, evidência selecionada, imunidade à refutação. A pergunta ética tem duas partes: acreditar nisso é uma falha moral, ou só intelectual? E vender, divulgar ou agir com base nisso é diferente de só acreditar?',
 lados=[('A crença é assunto privado; o problema é o dano', ['Liberdade de consciência: cada um tem direito a crer no que quiser, e a sociedade que policia crenças é pior do que a que tolera erros. O horóscopo lido por diversão não lesa ninguém.', 'O que importa é a ação: recusar tratamento eficaz para um filho, vender “cura” a quem está desesperado, espalhar medo de vacinas em epidemia. Aí há dano concreto e responsabilidade clara, e não é preciso julgar a crença para condenar o ato.', 'Humildade: a ciência também erra e muda; chamar tudo o que discorda dela de pseudociência é um abuso que a história desmente em alguns casos.']),
        ('Há uma ética da crença', ['Clifford: é errado crer sem evidência suficiente, porque crenças guiam ações e se espalham; quem crê mal por preguiça é como o armador que manda o navio sem inspeção e tem a sorte de ele não naufragar.', 'Responsabilidade epistêmica: ninguém escolhe crenças diretamente, mas escolhe como as forma: que fontes ouve, se busca contraprova, se tolera a dúvida. Essas escolhas são avaliáveis.', 'Pseudociências vivem de explorar vieses conhecidos (confirmação, anedota, autoridade) e de vulneráveis: doentes, enlutados, ansiosos. Quem as pratica profissionalmente lucra com a ignorância que ajuda a manter.', 'Dano difuso: cada crença sem base alimenta um ambiente em que a evidência deixa de decidir questões públicas; o custo aparece em saúde, em política e em confiança.'])],
 c=['As duas posições concordam no essencial: vender ou prescrever pseudociência como se fosse tratamento, sobretudo a quem está vulnerável, é errado, e ninguém sério defende o contrário.', 'A distinção útil não é crença versus ação, e sim o que está em jogo: quanto maior o risco para outros, maior o dever de verificar antes de crer e de agir. Um horóscopo e uma terapia para câncer não estão na mesma categoria.', 'Chamar alguém de “anticiência” raramente convence; a ética da crença se pratica melhor na primeira pessoa (como formo minhas crenças?) do que como acusação.'],
 p=('parcial', 'O peso está com a ética da crença, com uma gradação: crer sem base é uma falha que cresce em gravidade com o que a crença pode causar a outros, e passa a ser uma falta grave quando se vende, se prescreve ou se divulga pseudociência em situações de risco, como saúde e epidemias. A liberdade de consciência protege o direito de crer, não a isenção de responsabilidade pelo que a crença faz. A crítica sensata do outro lado é que a ciência não é infalível e que o rótulo deve ser usado com cuidado.'),
 teorias=[('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “crer segundo a evidência” produz uma sociedade com menos dano; crenças se espalham.'), ('deontologia-kantiana', 'Kant', 'Vender ilusão a quem está vulnerável é usar a pessoa; e a mentira é vedada mesmo quando “ajuda”.'), ('etica-das-virtudes', 'Virtudes', 'Honestidade intelectual e humildade são virtudes; a credulidade e a arrogância, vícios.'), ('utilitarismo-classico', 'Utilitarismo', 'Horóscopo inofensivo e antivacina em epidemia diferem só pelo dano; a crença em si não entra na conta.'), ('intuicionismo-moral', 'Intuicionismo', 'A intuição de que enganar o doente é errado não precisa de teoria para valer.')],
 licoes=['etica-da-crenca', 'fatos-e-valores', 'vieses-morais', 'epistemologia-moral'],
 fx=[('Science and Pseudo-Science (Stanford Encyclopedia)', SEP + 'pseudo-science/'), ('The Ethics of Belief (Stanford Encyclopedia)', SEP + 'ethics-belief/'), ('The Ethics of Belief', 'https://people.brandeis.edu/~teuber/Clifford_ethics.pdf'), ('Pseudoscience (Wikipédia)', WE + 'Pseudoscience')]),

dict(s='bolhas-e-camaras-de-eco', n='Bolhas e câmaras de eco: de quem é a culpa?', t=CV, r='Só ouvir quem concorda, e desconfiar de quem não. Até onde isso é uma falha pessoal, um desenho das plataformas ou um problema moral coletivo.',
 v='Uma bolha epistêmica é um ambiente em que vozes contrárias simplesmente não chegam; uma câmara de eco é um ambiente em que elas chegam e são desacreditadas de antemão, como fontes maliciosas. A distinção é de C. Thi Nguyen, e importa: a primeira se corrige com informação; a segunda, não, porque a câmara já ensinou a desconfiar de quem traz a informação. Os dois fenômenos cresceram com redes sociais que mostram o que retém a atenção. A pergunta é quem responde por isso e o que se deve fazer.',
 lados=[('Responsabilidade individual', ['Cada um escolhe o que ler, quem seguir e como reagir ao desacordo. Humildade intelectual, procurar a melhor versão da posição contrária e manter amigos que discordam são hábitos que dependem da pessoa, não do algoritmo.', 'A câmara de eco exige adesão: ela funciona porque o membro aceita desconfiar de todo mundo de fora. Essa aceitação é dele.', 'Tratar as pessoas como vítimas passivas das plataformas as infantiliza e tira o incentivo de mudar.']),
        ('Responsabilidade das plataformas e da sociedade', ['Os sistemas de recomendação otimizam engajamento, e indignação engaja; o desenho empurra para a polarização por decisão de empresa, não do usuário. Quem desenha o ambiente responde pelo que ele produz.', 'Sair de uma câmara de eco é caro: custa relações, pertencimento e, às vezes, segurança. Exigir isso de cada indivíduo ignora o que torna a saída possível ou não.', 'Mídia e instituições têm deveres: imprensa que confirma o que seu público quer ouvir, escolas que não ensinam a avaliar fontes, políticos que lucram com a divisão. O problema é de ecologia informacional, não de indivíduos isolados.', 'A evidência sobre o quanto as redes causam polarização é mista: parte da divisão vem de antes e de fora delas (televisão, geografia, partidos).'])],
 c=['A distinção de Nguyen decide o remédio: para bolhas basta expor a outras vozes; para câmaras de eco é preciso reconstruir a confiança, e isso não se faz com fatos, se faz com relações, o que exige tempo e pessoas de dentro.', 'As responsabilidades não se excluem: o usuário responde por seus hábitos, a plataforma pelo que seu desenho torna provável, a sociedade pelas instituições que ensinam ou não a pensar. A pergunta “de quem é a culpa?” tem resposta plural.', 'A virtude relevante aqui é antiga: a honestidade intelectual de quem prefere estar certo a ter razão.'],
 p=('parcial', 'O peso está com a responsabilidade compartilhada, com uma divisão clara: o desenho das plataformas é uma decisão que tem consequências previsíveis e por isso é moralmente avaliável; mas a câmara de eco só se fecha com a adesão de quem está dentro, e os hábitos de ouvir, duvidar e manter laços com quem discorda são deveres pessoais que ninguém pode cumprir pelo outro. A posição que culpa só os indivíduos ignora o ambiente; a que culpa só as plataformas ignora que o mesmo ambiente produz pessoas muito diferentes.'),
 teorias=[('etica-das-virtudes', 'Virtudes', 'Humildade intelectual, curiosidade e coragem de ouvir o contrário são virtudes epistêmicas.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras de desenho (o que recomendar, o que amplificar) devem ser julgadas pelo que produzem na sociedade.'), ('etica-do-discurso', 'Ética do discurso', 'A legitimidade das decisões coletivas depende de um debate em que todos possam ser ouvidos; a câmara de eco destrói essa condição.'), ('deontologia-kantiana', 'Kant', 'Explorar vieses para reter atenção trata o usuário como meio.'), ('pragmatismo', 'Pragmatismo', 'A democracia é uma comunidade de investigação; ela adoece quando as pessoas param de testar crenças juntas (Dewey).')],
 licoes=['tribalismo-moral', 'vieses-morais', 'etica-da-crenca', 'como-discutir-etica', 'etica-da-tecnologia'],
 fx=[('Echo Chambers and Epistemic Bubbles', 'https://doi.org/10.1017/epi.2018.32'), ('Echo chamber (Wikipédia)', WE + 'Echo_chamber_(media)'), ('Filter bubble (Wikipédia)', WE + 'Filter_bubble'), ('Social Epistemology (Stanford Encyclopedia)', SEP + 'epistemology-social/')]),

dict(s='pseudociencia-nas-universidades', n='É errado haver pseudociência nas universidades?', t=CV, r='Se há teorias blindadas e resultados que não se replicam na universidade, de quem é o dever de corrigir, o que ele exige e o que não justifica. A pergunta moral, com o diagnóstico junto.',
 v='Que existam resultados que não se replicam, teorias que nenhuma evidência abala e departamentos onde o desacordo tem custo é uma questão de fato, e a lição responde a ela com dados: existem, em partes de algumas áreas, e foram descobertos pela própria universidade. A pergunta deste debate é moral: isso é errado? Se é, de quem é a responsabilidade, o que ela exige (de quem pesquisa, de quem ensina, de quem financia e de quem critica), e que respostas à pseudociência seriam elas mesmas erradas, como desacreditar a instituição inteira?',
 lados=[('É errado, e a responsabilidade é de quem produz e abriga', ['Quem publica como sólido o que sabe frágil engana: a universidade vive da confiança pública, e vender resultado inflado ou teoria blindada como ciência é quebrar essa confiança com dinheiro público.', 'A crise de replicação não foi acidente: p-hacking, viés de publicação e amostras pequenas foram práticas normais por décadas, recompensadas por carreira e verba. Um sistema que premia o resultado positivo e não o verdadeiro tem uma falha moral, não só técnica.', 'Teorias que não se deixam testar e sobrevivem por adesão ocupam cadeiras, orientam teses e formam professores; os casos Sokal (1996) e dos “estudos de ressentimento” (2018) mostraram revistas aceitando textos sem sentido. Manter isso é formar gente para repetir, não para pensar.', 'Homogeneidade ideológica em certas áreas enfraquece a crítica interna: hipóteses incômodas deixam de ser testadas, e quem as levanta paga. Um ambiente em que discordar custa é um ambiente que escolheu não se corrigir.', 'O dano sai da universidade: políticas públicas, tratamentos e currículos escolares se apoiam em resultados que não existiam. Quem produz conhecimento para outros responde pelo que os outros fazem com ele.']),
        ('É errado, mas a culpa é dos incentivos, e a resposta errada é pior', ['A universidade é a única instituição que detectou e publicou a própria crise: a replicação em massa de 2015, o pré-registro e os dados abertos vieram de dentro. Um sistema que se audita cumpre o dever de corrigir, ainda que com atraso.', 'Generalizar é injusto e é desonesto: “partes de algumas áreas têm problemas” é verdade; “as universidades são antros de pseudociência” é uma acusação que seleciona escândalos e ignora que a maior parte do conhecimento confiável continua saindo delas.', 'Confusão de régua: filosofia, história, direito e crítica literária não são ciências empíricas nem se apresentam como tais; julgá-las por falseabilidade é um erro de categoria, não a descoberta de uma fraude.', 'Pesquisadores respondem ao que a carreira premia; a culpa moral de quem seguiu a norma é menor do que a de quem desenhou a norma. Responsabilizar o indivíduo e poupar o sistema de incentivos não resolve e é injusto.', 'Usar a pseudociência como pretexto para cortar verba, intervir em currículos ou desacreditar a universidade em bloco causa um dano maior do que o que pretende corrigir: entrega a produção de conhecimento a quem não tem método nenhum.'])],
 c=['Os dois lados concordam no veredito moral básico: publicar como sólido o que é frágil, blindar teorias contra a evidência e punir o desacordo são erros, não detalhes. A disputa é sobre de quem é a responsabilidade e sobre o que a resposta pode exigir.', 'Responsabilidade tem graus: maior para quem desenha incentivos (agências, revistas, comitês de carreira) e para quem ensina sem distinguir consenso, hipótese e interpretação; menor para quem seguiu a norma vigente; nenhuma para a instituição como abstração, que não age.', 'A crítica tem deveres próprios: a mesma honestidade que exige da universidade. Selecionar escândalos e generalizar é o viés que denuncia; e a crítica que serve para cortar verba sem reformar incentivos não corrige nada.', 'O diagnóstico, para quem quiser conferi-lo: a crise de replicação é real e documentada; as reformas (pré-registro, dados abertos, replicações) estão em curso e funcionam; parte das humanidades não é nem pretende ser ciência; a homogeneidade ideológica é medida em algumas áreas e discutida em outras.'],
 p=('parcial', 'A razão pesa para um veredito claro na parte moral e para uma distribuição de responsabilidade na parte prática. É errado haver pseudociência na universidade: ela existe para produzir e testar conhecimento com dinheiro público e confiança pública, e resultado inflado, teoria blindada e desacordo punido traem essa função e causam dano fora dela. A responsabilidade cai sobretudo sobre quem desenha os incentivos e sobre quem ensina sem separar o que é consenso do que é hipótese, menos sobre quem seguiu a norma, e nada sobre a “universidade” como abstração. A resposta moralmente certa é reformar incentivos e ensinar graus de evidência, o que a própria universidade já começou; a resposta errada é a generalização que desacredita a instituição inteira e serve para cortar o que não se quer reformar.'),
 teorias=[('etica-das-virtudes', 'Virtudes', 'Honestidade intelectual, coragem de publicar o resultado nulo e humildade diante dos dados são os deveres do pesquisador; a credulidade e a arrogância, os vícios.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Julgue as normas (pré-registro, revisão, incentivos de carreira) pelo conhecimento confiável que produzem, e mude as que produzem o contrário.'), ('deontologia-kantiana', 'Kant', 'Publicar o que se sabe frágil como se fosse sólido é enganar; o dever de veracidade não tem exceção para a carreira nem para a causa.'), ('pragmatismo', 'Pragmatismo', 'O valor do conhecimento está em sobreviver ao teste público; uma comunidade que para de testar deixa de conhecer e de merecer confiança (Peirce, Dewey).'), ('etica-do-discurso', 'Ética do discurso', 'A universidade só cumpre sua função se todo argumento puder ser contestado sem custo para quem contesta; punir o desacordo é a falha de fundo.')],
 licoes=['etica-da-crenca', 'responsabilidade-coletiva', 'fatos-e-valores', 'argumentos-morais', 'vieses-morais', 'como-discutir-etica'],
 fx=[('Replication crisis (Wikipédia)', WE + 'Replication_crisis'), ('Estimating the reproducibility of psychological science', 'https://doi.org/10.1126/science.aac4716'), ('Sokal affair (Wikipédia)', WE + 'Sokal_affair'), ('Grievance studies affair (Wikipédia)', WE + 'Grievance_studies_affair'), ('Science and Pseudo-Science (Stanford Encyclopedia)', SEP + 'pseudo-science/'), ('The Ethics of Belief (Stanford Encyclopedia)', SEP + 'ethics-belief/'), ('Center for Open Science', 'https://www.cos.io/')]),
dict(s='censura', n='Censura: quando é legítimo impedir que algo seja dito?', t=LD, r='Estado, plataformas, editoras, público: muitos podem silenciar. O que separa a proibição legítima de incitação e fraude da censura de opiniões.',
 v='Censurar é impedir, por força, que algo seja dito ou visto. Quase ninguém defende censura de opiniões; quase ninguém defende que tudo possa ser dito (ameaças, fraude, material de abuso infantil, segredo médico). O debate real é sobre a fronteira e sobre quem a traça: o Estado, com lei; as plataformas, com moderação; o público, com pressão. Veja também o debate sobre liberdade de expressão irrestrita e o paradoxo da tolerância.',
 lados=[('Contra a censura: presunção forte de liberdade', ['Mill: ninguém é infalível; silenciar uma opinião pode silenciar uma verdade, e mesmo a opinião falsa obriga a verdade a se defender e a se entender melhor. A censura faz mal a quem é impedido de ouvir, não só a quem é impedido de falar.', 'Quem decide? Toda censura exige um censor, e o poder de calar é usado contra quem não tem poder: a história da censura é a história de minorias, dissidentes e cientistas silenciados por autoridades convencidas de estar certas.', 'Efeito inverso: ideias proibidas ganham aura de verdade reprimida; a melhor resposta ao discurso ruim costuma ser mais discurso, e a pior, a prova de que o poder teme o argumento.', 'A fronteira derrapa: o que começa como proibição de ódio vira proibição de ofensa, depois de crítica, depois de desacordo.']),
        ('A favor de limites: a palavra também causa dano', ['Há falas que são atos: ameaçar, incitar violência iminente, fraudar, difamar, expor a vida privada de alguém. Nenhuma teoria da liberdade de expressão as protege, e proibi-las não é censurar opiniões.', 'Dano ao discurso: quando a intimidação e o assédio expulsam pessoas do debate, a liberdade de expressão de quem foi expulso diminui. Limites podem proteger o debate, não só restringi-lo.', 'Casos extremos: a rádio que convocou o genocídio em Ruanda não foi uma “opinião”; propaganda de extermínio tem história e efeitos conhecidos. Popper: a tolerância ilimitada leva ao desaparecimento da tolerância.', 'Plataformas não são praças: moderação de conteúdo por uma empresa privada não é censura estatal, e deixar de moderar também é uma escolha com consequências (desinformação em epidemias, assédio em massa).'])],
 c=['Os dois lados aceitam a distinção central: entre proibir atos feitos com palavras (incitação iminente, ameaça, fraude, difamação, exposição de privacidade) e proibir opiniões, inclusive as odiosas. O primeiro grupo é restrito e definido; o segundo é onde a censura começa.', 'O argumento “quem decide?” é o mais forte contra ampliar a lista: toda ampliação é uma ferramenta que mudará de mãos. Por isso a presunção contra a censura estatal de opinião é muito forte nas democracias, e as exceções são estreitas, atuais e específicas.', 'A moderação de plataformas é um problema diferente, e novo: não é o Estado, mas tem o poder de silenciar em escala. A preocupação legítima dos dois lados é a mesma: concentração do poder de decidir o que se ouve.', 'Pressão social (boicote, crítica pública) não é censura; ela é exercício de expressão. Vira problema quando se converte em intimidação, e isso o debate sobre cancelamento trata.'],
 p=('parcial', 'O peso está com a presunção forte contra a censura: o Estado não deve proibir opiniões, mesmo falsas ou odiosas, e as exceções legítimas são atos feitos com palavras, definidos de forma estreita: incitação a violência iminente, ameaça, fraude, difamação, exposição de dados privados e material de abuso. Essa é a posição dominante em filosofia política liberal e nas democracias. A crítica acerta ao mostrar que a palavra causa dano e que a ausência de limites também silencia; o ponto em aberto, e sem consenso, é a moderação por plataformas, onde o poder de calar é privado, global e opaco.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo (Mill)', 'A liberdade de expressão maximiza a chance de a verdade aparecer; as exceções são as falas que causam dano direto.'), ('deontologia-de-direitos', 'Direitos', 'Expressão é um direito que limita o Estado; só cede diante de direitos alheios (segurança, reputação, privacidade).'), ('contratualismo-escanloniano', 'Scanlon', 'Ninguém poderia razoavelmente aceitar um princípio que entregue ao Estado o poder de decidir o que pode ouvir.'), ('contratualismo-rawlsiano', 'Rawls', 'Liberdade de expressão é liberdade básica, protegida pelo primeiro princípio; limites só para proteger as outras liberdades.'), ('etica-do-discurso', 'Ética do discurso', 'A legitimidade depende de um debate aberto; a censura o corrompe, e a intimidação também.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Compare as regras: uma sociedade que proíbe opiniões é pior, a longo prazo, do que uma que tolera falas ruins.')],
 licoes=['da-etica-a-politica', 'direitos-e-limiares', 'economia-politica-e-etica', 'etica-da-tecnologia'],
 fx=[('Freedom of Speech (Stanford Encyclopedia)', SEP + 'freedom-speech/'), ('On Liberty (Wikipédia)', WE + 'On_Liberty'), ('Censorship (Wikipédia)', WE + 'Censorship'), ('Paradox of tolerance (Wikipédia)', WE + 'Paradox_of_tolerance'), ('A Theory of Freedom of Expression', 'https://www.jstor.org/stable/2264971')]),
dict(s='mudar-o-meio-ou-as-pessoas', n='Mudar o meio ou mudar a cabeça das pessoas?', t=RS, r='Convencer um a um ou mudar leis, preços, tecnologia e padrões? A estratégia de quem quer um mundo melhor, e o que a psicologia diz sobre ela.',
 v='Quem quer reduzir um mal (a pobreza, o sofrimento animal, a corrupção, as emissões) tem dois caminhos: mudar o que as pessoas pensam, para que escolham diferente, ou mudar o meio em que escolhem: leis, preços, regras, tecnologia, o que é padrão e o que é fácil. Movimentos sociais dividem-se nisso há dois séculos, e a defesa animal é um exemplo claro: conversão individual ou campanhas por mudança institucional e tecnológica.',
 lados=[('Mudar o meio', ['Situacionismo: o comportamento responde muito mais ao ambiente do que às convicções declaradas. A maioria das pessoas que condena a criação industrial continua comprando o que ela produz; quando o preço, a conveniência ou a norma mudam, o comportamento muda sem conversão.', 'Escala: uma lei, um padrão de indústria ou uma tecnologia (a carne cultivada, a energia barata e limpa) muda o comportamento de milhões de uma vez; a persuasão um a um não escala e regride.', 'Durabilidade: mudanças institucionais criam novos normais, e o normal educa: as gerações seguintes já nascem dentro da nova regra e a acham óbvia. Foi assim com o cinto de segurança, o fumo em locais fechados e boa parte dos direitos civis.', 'A exigência de convencer todos antes de mudar algo é paralisante; a história do progresso moral é a de minorias que mudaram regras antes de mudar maiorias.']),
        ('Mudar as pessoas', ['Legitimidade: mudar regras sem mudar convicções produz leis que não se cumprem, retrocessos na primeira eleição e ressentimento. O que não é entendido não se sustenta.', 'As instituições são feitas de pessoas: quem vota, legisla, fiscaliza e inventa a tecnologia precisou primeiro achar que valia a pena. Toda mudança de meio foi precedida de uma mudança de cabeça em alguém.', 'Autonomia: moldar o ambiente para que as pessoas façam o certo sem perceber trata-as como peças; a educação moral trata-as como agentes. Veja o debate sobre paternalismo.', 'Transferência: quem mudou de convicção leva a mudança para todas as situações; quem só respondeu a um incentivo volta atrás quando ele acaba.'])],
 c=['A dicotomia é falsa como oposição e verdadeira como ordem de prioridade: as duas coisas se alimentam, mas o que a evidência mostra é que a mudança de meio costuma vir antes e a mudança de convicções a segue, não o contrário. A norma social é o mecanismo que liga as duas.', 'A persuasão funciona melhor com minorias ativas (as que vão legislar, fundar, inventar) do que com a maioria; e a mudança de meio funciona melhor quando uma minoria convencida já existe para sustentá-la.', 'A objeção da autonomia é forte contra manipulação e fraca contra transparência: tornar o certo mais fácil e dizer por quê respeita o agente; esconder o porquê, não.'],
 p=('parcial', 'O peso está com mudar o meio, com uma condição: a evidência da psicologia e da história mostra que leis, preços, padrões e tecnologia mudam o comportamento de muitos de uma vez e que as convicções tendem a acompanhar o novo normal, enquanto a conversão individual não escala e regride. Mas mudanças de meio sem uma minoria convencida que as defenda não se sustentam, e uma mudança de meio imposta por manipulação desrespeita as pessoas. A estratégia mais defendida é a dupla: convencer os que vão mudar as regras, e mudar as regras para que o certo seja o fácil, dizendo por quê.'),
 teorias=[('consequencialismo-de-regras', 'Consequencialismo de regras', 'Julgue a estratégia pelo que produz em escala; a mudança de regra costuma vencer.'), ('etica-das-virtudes', 'Virtudes', 'O caráter se forma pelo hábito, e o hábito pelo meio: Aristóteles concordaria com os dois lados.'), ('deontologia-kantiana', 'Kant', 'Moldar escolhas às escondidas trata as pessoas como meios; informar e persuadir as trata como fins.'), ('pragmatismo', 'Pragmatismo', 'Instituições são hábitos coletivos; mudá-las é educar em escala (Dewey).'), ('sencientismo', 'Sencientismo', 'Na defesa animal, a mudança institucional e tecnológica tem reduzido mais sofrimento do que a conversão individual.')],
 licoes=['situacionismo-e-experimentos', 'progresso-moral', 'animais-e-a-politica', 'etica-animal-na-pratica', 'educacao-moral', 'da-etica-a-politica'],
 fx=[('Social norm (Wikipédia)', WE + 'Social_norm'), ('Nudge (Wikipédia)', WE + 'Nudge_(book)'), ('Moral Character (Stanford Encyclopedia)', SEP + 'moral-character/'), ('Animal Charity Evaluators', 'https://animalcharityevaluators.org/'), ('The Expanding Circle', 'https://www.google.com/search?tbm=bks&q=Singer+The+Expanding+Circle')]),

dict(s='qual-vertente-politica', n='Qual vertente política leva a um mundo melhor?', t=JE, r='Esquerda, direita, liberalismo, socialismo, conservadorismo: o que a evidência e a filosofia moral permitem dizer, e o que nenhuma delas ainda inclui.',
 v='A pergunta parece a mais partidária de todas, mas tem uma parte respondível. Se “mundo melhor” significa menos sofrimento, mais bem-estar, direitos protegidos e progresso que dura, é possível olhar a história e os dados e perguntar que arranjos produziram isso. A resposta tem um núcleo de consenso e uma margem de disputa legítima, e deixa de fora um grupo que nenhuma vertente tradicional representa.',
 lados=[('O que há de consenso', ['Democracia liberal com Estado de direito: regimes com eleições competitivas, imprensa livre, tribunais independentes e direitos protegidos produziram, em média, mais bem-estar, menos fome, menos guerra entre si e nenhuma das grandes fomes do século XX, que ocorreram todas sob autocracias (Sen).', 'Contra os extremos: os regimes totalitários de esquerda e de direita do século XX foram as maiores catástrofes morais produzidas por seres humanos; a filosofia moral é quase unânime em rejeitar qualquer vertente que suspenda direitos em nome de um fim, por mais nobre que soe.', 'Economia de mercado com Estado social: os países que combinam mercado, Estado de direito e um Estado de bem-estar substancial (os nórdicos são o caso típico) estão no topo de quase todas as medidas de bem-estar, confiança e mobilidade.', 'Ciência e abertura: vertentes que subordinam a evidência à doutrina erram mais, e demoram mais para corrigir.']),
        ('O que é disputa legítima', ['Quanto redistribuir: igualitaristas e prioritaristas defendem mais; liberais clássicos e conservadores alertam para incentivos, concentração de poder estatal e perda de liberdade. Os dados mostram trade-offs reais e nenhuma resposta única.', 'Tamanho do Estado e das empresas: a esquerda teme o poder econômico concentrado; a direita, o poder político concentrado. Os dois medos têm histórico que os justifica.', 'Tradição e mudança: conservadores dizem que instituições encarnam sabedoria acumulada e que reformas rápidas quebram o que não entendem; progressistas dizem que o mesmo argumento defendeu a escravidão e a exclusão das mulheres. Os dois têm casos a favor.', 'Nação e cosmopolitismo: deveres com os compatriotas contra deveres com todos; veja o debate sobre imigração.']),
        ('O que nenhuma vertente inclui', ['Nenhuma corrente política tradicional conta os animais: direita e esquerda assumem que o mundo melhor é o mundo melhor para humanos, e a criação industrial cresce sob todos os governos. Pelo número de seres afetados, essa é a maior omissão de todas as plataformas.', 'Gerações futuras e riscos catastróficos: sistemas eleitorais de quatro anos não representam quem ainda não nasceu; a vertente que levar isso a sério ainda não existe como força política (Zoopolis, longoprazismo).'])],
 c=['A resposta honesta separa níveis: há consenso amplo contra o autoritarismo e a favor da democracia liberal com Estado social; há disputa legítima, com argumentos e dados dos dois lados, sobre quanto Estado e quanta redistribuição; e há uma falha comum a todos: o círculo moral de toda vertente tradicional para na espécie e na geração presente.', 'Rotular (esquerda, direita) esconde que a maioria das políticas boas foi adotada por governos de ambos os lados e que as piores catástrofes também vieram de ambos. O critério não é o rótulo, e sim o teste: protege direitos, corrige-se com evidência, e inclui quem está fora?', 'O debate ético sobre política é mais produtivo quando se faz política por política (esta regra, com estes efeitos, para estes seres) do que por vertente.'],
 p=('parcial', 'O peso está com um núcleo que a evidência sustenta: democracia liberal com Estado de direito, economia de mercado e Estado social substancial produziu mais bem-estar e menos catástrofe do que qualquer alternativa testada, e as vertentes autoritárias de qualquer sinal foram as piores. Dentro desse núcleo, a disputa entre mais e menos redistribuição, mais e menos Estado, é legítima e sem vencedor claro: depende de trade-offs que os dados mostram e de pesos morais que as teorias dividem. O que a ética acrescenta é um critério que nenhuma vertente atual cumpre: o mundo melhor inclui os animais e as gerações futuras, e a vertente que levar isso a sério não está no espectro de hoje.'),
 teorias=[('contratualismo-rawlsiano', 'Rawls', 'Liberdades básicas iguais e desigualdade só se beneficiar os que estão pior: o fundamento filosófico do Estado social.'), ('deontologia-de-direitos', 'Direitos (Nozick)', 'O Estado mínimo protege direitos e nada mais; redistribuir é violar.'), ('prioritarismo', 'Prioritarismo', 'Julgue a política pelo que faz por quem está pior, onde quer que esteja.'), ('utilitarismo-classico', 'Utilitarismo', 'Compare os arranjos pelo bem-estar total que produzem; é o critério dos dados, e inclui os animais se levado a sério.'), ('sencientismo', 'Sencientismo', 'Nenhuma vertente atual conta os seres que mais sofrem sob qualquer governo.'), ('confucionismo', 'Confucionismo', 'A ordem política depende da virtude de quem governa, não só das regras: a tradição tem valor.')],
 licoes=['da-etica-a-politica', 'economia-politica-e-etica', 'somar-priorizar-ou-garantir', 'catastrofes-morais', 'animais-e-a-politica', 'geracoes-futuras'],
 fx=[('Development as Freedom', 'https://www.google.com/search?tbm=bks&q=Amartya+Sen+Development+as+Freedom'), ('Liberalism (Stanford Encyclopedia)', SEP + 'liberalism/'), ('Conservatism (Stanford Encyclopedia)', SEP + 'conservatism/'), ('Socialism (Stanford Encyclopedia)', SEP + 'socialism/'), ('Distributive Justice (Stanford Encyclopedia)', SEP + 'justice-distributive/'), ('Our World in Data: Democracy', 'https://ourworldindata.org/democracy')]),
dict(s='preferencias-postumas', n='Preferências póstumas: o que o morto quis ainda conta?', t=VM, r='Testamentos, promessas ao leito de morte, o destino do corpo. A pessoa não existe mais; sua vontade deve pesar? O debate sobre dano e interesses póstumos.',
 v='Alguém pede que, depois da morte, suas cartas sejam queimadas, seu corpo seja doado, sua obra não seja publicada, seu dinheiro vá para uma causa. Quando chega a hora, a pessoa não existe mais: não vai saber, não vai sofrer, não vai se alegrar. Ainda assim quase todas as sociedades cumprem testamentos e julgam feio trair uma promessa feita a quem morreu. A filosofia chama isso de problema dos interesses póstumos, ou do dano póstumo: um desejo pode ser frustrado quando não há mais quem o tenha? E, se pode, quanto deve pesar contra as necessidades de quem está vivo?',
 lados=[('A preferência conta: há interesses que sobrevivem ao sujeito', ['Teorias do desejo: o bem-estar inclui ter os desejos realizados no mundo, não só sentir que foram. Se isso vale em vida para o que a pessoa nunca vai saber (veja o debate sobre dano sem experiência), vale depois da morte pelo mesmo motivo: o desejo de que a obra seja preservada é frustrado se ela é destruída, com ou sem sujeito para perceber.', 'Feinberg e Pitcher: quem é prejudicado não é o cadáver, e sim a pessoa que viveu (a pessoa ante mortem), cujos interesses em vida alcançavam o futuro. Dizer que o pianista foi prejudicado pela destruição póstuma de suas gravações é dizer algo sobre a vida dele, que ficou pior do que ele acreditava.', 'Promessas: uma promessa feita ao moribundo obriga pela mesma razão que qualquer promessa: por quem a fez, não por quem a recebe. Que o destinatário não possa cobrar não a anula; torna a traição mais fácil, e por isso mais feia.', 'Confiança entre vivos: a prática de honrar testamentos é o que permite que cada vivo planeje além da própria vida: doar órgãos, deixar herança, fundar algo. Quebrá-la depois da morte de um é tirar essa segurança de todos.']),
        ('A preferência não conta, ou conta só indiretamente', ['Problema do sujeito (Epicuro): dano exige alguém prejudicado; depois da morte não há ninguém. Dizer que a pessoa ante mortem foi lesada por um evento posterior parece exigir que o futuro altere o passado.', 'Experiencialismo: o que não entra na experiência de ninguém não muda o bem-estar de ninguém; o desejo do morto é um fato sobre o passado, não um interesse presente.', 'Desejos condicionais (Parfit, Williams): muitos desejos são condicionais à própria existência, como o de ler um livro ou viajar; não faz sentido dizer que foram frustrados pela morte. Só os desejos incondicionais sobre o mundo, se existem, poderiam sobreviver, e nem todos os pedidos póstumos são desse tipo.', 'Os vivos primeiro: as necessidades de quem existe pesam mais do que as vontades de quem não existe. A mão morta do testador não pode governar os vivos para sempre; por isso o direito limita a duração de fideicomissos e permite quebrar cláusulas absurdas.', 'Decaimento: a força de uma vontade póstuma diminui com o tempo. Ninguém se sente obrigado pelos desejos de um antepassado de dez gerações; algo entre o funeral e esse ponto vai perdendo peso.'])],
 c=['O nome da família de teorias em jogo é preferencialismo: as teorias em que o bem-estar consiste na satisfação de preferências, como o utilitarismo de preferências de Hare e Singer e as teorias do desejo. As preferências póstumas são um dos testes clássicos do preferencialismo: se preferências contam mesmo quando não são sentidas, as do morto contam; se só contam quando sentidas, o preferencialismo desliza para o hedonismo. O debate, porém, é mais amplo do que uma teoria: também a deontologia (promessas) e o consequencialismo de regras (confiança) têm o que dizer sobre o que o morto quis.', 'Os dois lados costumam concordar na prática (cumprir testamentos e promessas razoáveis; não deixar o morto governar os vivos indefinidamente) e discordar no fundamento: dano direto à pessoa que viveu, ou dever dos vivos para com a prática que os protege.', 'A objeção do sujeito é respondida pela distinção entre o cadáver e a pessoa que viveu: ninguém diz que o corpo é prejudicado; diz-se que a vida que houve ficou pior, como quando descobrimos que um casamento feliz foi uma farsa desde o início. O preço dessa resposta é aceitar que um fato posterior pode afetar o valor de uma vida já encerrada, e muitos aceitam.', 'A distinção de Parfit entre desejos condicionais e incondicionais é a ferramenta mais útil: o desejo de que o filho seja cuidado ou de que a obra sobreviva não depende de o autor existir para vê-lo; o desejo de aproveitar a aposentadoria, sim. Só os primeiros fundam um interesse póstumo.', 'O decaimento no tempo e a prioridade dos vivos não negam o interesse póstumo; dão-lhe um peso finito, que a maioria das teorias aceita.'],
 p=('parcial', 'O peso está com dar às preferências póstumas um valor real, e finito: a maioria dos filósofos do bem-estar rejeita o requisito da experiência e aceita, com Feinberg e Pitcher, que a pessoa que viveu pode ser lesada por eventos posteriores à morte quando eles frustram desejos incondicionais sobre o mundo; e mesmo quem recusa o dano direto reconhece o dever de honrar promessas e testamentos, pela confiança que isso dá a todos os vivos. O que os dois lados também aceitam é o limite: o interesse póstumo cede às necessidades sérias dos vivos, perde força com o tempo e não cobre pedidos que exigiriam prejudicar outros. O nome técnico do tema é dano póstumo (ou interesses póstumos), e a objeção clássica é o problema do sujeito, de Epicuro.'),
 teorias=[('utilitarismo-de-preferencias', 'Preferências', 'Um desejo incondicional sobre o mundo é frustrado pela sua não realização, haja ou não quem o sinta.'), ('utilitarismo-classico', 'Hedonismo', 'Sem experiência, sem dano; o testamento vale pela segurança que dá aos vivos.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra de honrar vontades póstumas produz confiança e planejamento; a de ignorá-las, não.'), ('deontologia-kantiana', 'Kant', 'A promessa obriga por quem prometeu; a morte do credor não dissolve o dever.'), ('contratualismo-escanloniano', 'Scanlon', 'Ninguém rejeitaria razoavelmente um princípio que proteja o que deixamos para depois de nós.'), ('etica-das-virtudes', 'Virtudes', 'A fidelidade a quem morreu é parte da lealdade; e a sabedoria prática sabe quando ela deve ceder.')],
 licoes=['teorias-do-bem-estar', 'geracoes-futuras', 'kant-e-o-imperativo-categorico', 'etica-populacional'],
 fx=[('Death (Stanford Encyclopedia)', SEP + 'death/'), ('Well-Being (Stanford Encyclopedia)', SEP + 'well-being/'), ('The Misfortunes of the Dead', 'https://www.jstor.org/stable/20014009'), ('Harm to Others', 'https://www.google.com/search?tbm=bks&q=Joel+Feinberg+Harm+to+Others'), ('Reasons and Persons', 'https://www.google.com/search?tbm=bks&q=Parfit+Reasons+and+Persons'), ('Death: Posthumous Harm (Stanford Encyclopedia)', SEP + 'death/#PosHar')]),
]
